import {mountPianoRoll} from './music-piano-roll.js';
import {arrangeSections} from './music-arrange.js';
import {referenceComposer} from './music-reference-ui.js';
import {musicScore,findMotifs,composeFromReference,composeFromReferences,referenceStyle} from './music-motifs.js';
import {compileMusic,checkScore,writeMIDI,MUSIC_MOODS,MUSIC_KEYS,MUSIC_SCALES} from './music-compose.js';

export function musicAnalysis(api){
 const $=s=>document.querySelector(s),esc=api.esc;
 function open(t,draft=null,settings={}){
  const decoded=draft?{score:draft,warnings:settings.warnings||[]}:musicScore(t.asset),score=structuredClone(decoded.score);let part=settings.part||0,page=settings.page||0,match=settings.match||'transpose',selected=null,highlight=true,motifs=findMotifs(score,{match}),undo=[],rollTool='select',quantum=6,barsPerPage=2,redo=[];
  const option=(v,label,current)=>`<option value="${esc(String(v))}" ${String(v)===String(current)?'selected':''}>${esc(label)}</option>`;
  api.modal('Notes & motifs · '+t.name,`<p>Edit a copy. Select riff marks A–B; Move / resize edits notes. Your source stays intact.</p><div class="studio-grid music-analysis-context"><label>Part<select id="analysisPart">${score.tracks.map((tr,i)=>option(i,tr.name||'Part '+(i+1),part)).join('')}</select></label>${score.songSections?.length?`<label>Song section<select id="analysisSection">${score.songSections.map(v=>option(v.start,v.name+' · bar '+(v.start/96+1),0)).join('')}</select></label>`:''}</div><details class="music-detection"><summary>Find and highlight repeated motifs</summary><div class="studio-grid"><label>Match<select id="analysisMatch">${[['transpose','Melody + rhythm, allow transposition'],['exact','Exact pitches + rhythm'],['rhythm','Rhythm only'],['contour','Melodic contour + rhythm']].map(([v,l])=>option(v,l,match)).join('')}</select></label></div><label><input type="checkbox" id="analysisHighlight" checked> Highlight motifs</label><label>Detected motifs<select id="analysisMotif"></select></label></details><div class="studio-actions"><button id="analysisPrev" type="button">Previous bars</button><button id="analysisNext" type="button">Next bars</button><button id="analysisOriginal" type="button" ${t.asset?'':'disabled'}>▶ Original</button><button id="analysisPreview" type="button">▶ Edited song</button><button id="analysisHearRange" type="button">▶ Loop selected riff</button><button id="analysisStop" type="button">Stop</button></div><p id="analysisStatus" class="studio-status"></p><div class="studio-actions roll-tools">${[['select','Move / resize'],['draw','Draw notes'],['erase','Erase'],['range','Select riff'],['scroll','Scroll']].map(([v,l])=>`<button type="button" data-roll-tool="${v}" aria-pressed="${v==='select'}">${l}</button>`).join('')}<label>Visible bars<select id="analysisZoom"><option>1</option><option selected>2</option><option>4</option><option>8</option></select></label><label>Snap<select id="analysisSnap"><option value="24">Beat · ¼</option><option value="12">½ beat · ⅛</option><option value="6" selected>¼ beat · ¹⁄₁₆</option><option value="8">Triplet</option><option value="3">⅛ beat · ¹⁄₃₂</option></select></label></div><p>Tap a note to edit it. Drag to move it; drag its dark right edge to change its length. Draw adds notes. Select riff marks the reference range.</p><div class="music-roll touch-roll" id="analysisRoll"></div><div id="analysisNote"></div><details><summary>Notes on this page</summary><div id="analysisNoteList" class="music-note-list"></div></details><div class="studio-grid"><label>Range start (tick)<input id="analysisStart" type="number" min="0" value="0"></label><label>Range end (tick)<input id="analysisEnd" type="number" min="1" value="${Math.min(96,score.length)}"></label></div><p>24 ticks = one beat; 96 ticks = one four-beat bar. Choose a detected occurrence or enter a range yourself.</p><div class="studio-actions"><button id="analysisAdd" type="button">Add note</button><button id="analysisUndo" type="button" disabled>Undo note edit</button><button id="analysisRedo" type="button" disabled>Redo</button><button id="analysisTransposeUp" type="button">Selected riff + semitone</button><button id="analysisTransposeDown" type="button">Selected riff − semitone</button><button id="analysisQuantize" type="button">Snap selected riff</button><button id="analysisDeleteRange" type="button">Delete selected notes</button><button id="analysisMIDI" type="button">Export edited MIDI</button><button id="analysisGenerate" type="button">Compose from this reference</button></div>${decoded.warnings.length?`<p class="hint-line">${decoded.warnings.map(esc).join('<br>')}</p>`:''}<p class="hint-line">Only the note score is edited. Native effects and instrument changes require arranging when saving a new track. The source track remains available.</p>`,()=>api.arrange({score:structuredClone(score),name:t.name+' edited',warnings:decoded.warnings,bankId:settings.bankId??t.id,bankAsset:settings.bankAsset,loop:settings.loop}),'Arrange a copy');
  function draw(){const list=motifs.filter(g=>g.track===part);$('#analysisMotif').innerHTML='<option value="">Choose a repeated phrase</option>'+list.map(g=>option(g.id,`${g.count} notes · ${g.occurrences.length} occurrences · bar ${Math.floor(g.occurrences[0].start/96)+1}`,'')).join('');drawRoll();}
  function drawRoll(){const tr=score.tracks[part],groups=motifs.filter(g=>g.track===part),colours=['#9d6cd6','#2a9e86','#b9732c','#6484c6','#bf5590'];const range={start:+$('#analysisStart').value,end:+$('#analysisEnd').value};
   const bounds=mountPianoRoll({root:$('#analysisRoll'),score,part,page,barsPerPage,tool:rollTool,quantum,range,colour:index=>{const i=highlight?groups.findIndex(g=>g.occurrences.some(o=>o.indices.includes(index))):-1;return i<0?null:colours[i%colours.length];},onSelect:edit,onChange:notes=>{remember();score.tracks[part].notes=notes;changed();},onRange:r=>{$('#analysisStart').value=r.start;$('#analysisEnd').value=r.end;},error:api.error});
   page=bounds.page;const visible=tr.notes.map((n,index)=>({...n,index})).filter(n=>n.tick<bounds.end&&n.tick+n.duration>bounds.start);$('#analysisNoteList').innerHTML=visible.slice(0,96).map(n=>`<button type="button" data-analysis-note="${n.index}">${MUSIC_KEYS[n.key%12]}${Math.floor(n.key/12)-1} · bar ${Math.floor(n.tick/96)+1}</button>`).join('');
   $('#analysisStatus').textContent=`Bars ${page*barsPerPage+1}–${Math.ceil(bounds.end/96)} · ${tr.notes.length} notes · ${groups.length} repeated phrases`;$('#analysisPrev').disabled=page===0;$('#analysisNext').disabled=bounds.end>=score.length;document.querySelectorAll('[data-analysis-note]').forEach(b=>b.onclick=()=>edit(+b.dataset.analysisNote));
  }
  function remember(){redo=[];$('#analysisRedo').disabled=true;undo.push(structuredClone(score.tracks[part].notes));if(undo.length>10)undo.shift();$('#analysisUndo').disabled=false;}
  function changed(){score.tracks[part].notes.sort((a,b)=>a.tick-b.tick||a.key-b.key);motifs=findMotifs(score,{match});selected=null;$('#analysisNote').innerHTML='';draw();}
  function edit(index){selected=index;document.querySelectorAll('[data-note-body]').forEach(el=>{el.setAttribute('stroke',+el.dataset.noteBody===index?'#9c6810':'none');el.setAttribute('stroke-width','3');});const n=score.tracks[part].notes[index];$('#analysisNote').innerHTML=`<label>Note<select id="analysisPitch">${Array.from({length:128},(_,key)=>option(key,MUSIC_KEYS[key%12]+(Math.floor(key/12)-1),n.key)).join('')}</select></label><div class="studio-grid">${[['Start tick','analysisTick',n.tick,0,score.length-1],['Duration ticks','analysisDuration',n.duration,1,score.length],['Velocity','analysisVelocity',n.velocity,1,127]].map(([l,id,value,min,max])=>`<label>${l}<input id="${id}" type="number" min="${min}" max="${max}" value="${value}"></label>`).join('')}</div><div class="studio-actions"><button id="analysisApply" type="button">Apply note edit</button><button id="analysisDelete" type="button">Delete note</button></div>`;$('#analysisApply').onclick=safe(()=>{const next={tick:+$('#analysisTick').value,duration:+$('#analysisDuration').value,key:+$('#analysisPitch').value,velocity:+$('#analysisVelocity').value},copy=structuredClone(score);copy.tracks[part].notes[index]=next;checkScore(copy,{arranging:true});remember();score.tracks[part].notes[index]=next;changed();});$('#analysisDelete').onclick=()=>{remember();score.tracks[part].notes.splice(index,1);changed();};}
  const safe=fn=>async()=>{try{await fn();}catch(e){api.error(e);}};
  if($('#analysisSection'))$('#analysisSection').onchange=()=>{page=Math.floor(+$('#analysisSection').value/(barsPerPage*96));drawRoll();};document.querySelectorAll('[data-roll-tool]').forEach(b=>b.onclick=()=>{rollTool=b.dataset.rollTool;document.querySelectorAll('[data-roll-tool]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));drawRoll();});$('#analysisZoom').onchange=()=>{const at=page*barsPerPage*96;barsPerPage=+$('#analysisZoom').value;page=Math.floor(at/(barsPerPage*96));drawRoll();};$('#analysisSnap').onchange=()=>{quantum=+$('#analysisSnap').value;drawRoll();};for(const id of ['analysisStart','analysisEnd'])$('#'+id).onchange=drawRoll;
  $('#analysisPreview').onclick=safe(()=>api.play(compileMusic(settings.bankAsset||score.composition?.version===2?score:{...score,tracks:score.tracks.map((t,i)=>({...t,program:t.channel===9?3:i%3}))},{bankAsset:settings.bankAsset||null})));$('#analysisHearRange').onclick=safe(()=>{const clip=arrangeSections({...score,tracks:[{...score.tracks[part],program:settings.bankAsset||score.composition?.version===2?score.tracks[part].program:0}]},[{from:+$('#analysisStart').value,to:+$('#analysisEnd').value}]);clip.loopStart=0;return api.play(compileMusic(clip,{bankAsset:settings.bankAsset||null}));});
  $('#analysisPart').onchange=()=>{part=+$('#analysisPart').value;page=0;undo=[];redo=[];$('#analysisRedo').disabled=true;$('#analysisUndo').disabled=true;$('#analysisNote').innerHTML='';draw();};$('#analysisMatch').onchange=()=>{match=$('#analysisMatch').value;motifs=findMotifs(score,{match});draw();};$('#analysisHighlight').onchange=()=>{highlight=$('#analysisHighlight').checked;drawRoll();};$('#analysisPrev').onclick=()=>{page--;drawRoll();};$('#analysisNext').onclick=()=>{page++;drawRoll();};$('#analysisOriginal').onclick=safe(()=>api.play(t.asset));$('#analysisStop').onclick=api.stop;
  $('#analysisMotif').onchange=()=>{const g=motifs.find(g=>g.id===$('#analysisMotif').value);if(!g)return;$('#analysisStart').value=g.occurrences[0].start;$('#analysisEnd').value=g.occurrences[0].end;page=Math.floor(g.occurrences[0].start/(barsPerPage*96));drawRoll();};
  $('#analysisAdd').onclick=()=>{remember();const tick=Math.min(score.length-1,page*barsPerPage*96);score.tracks[part].notes.push({tick,duration:Math.min(12,score.length-tick),key:60,velocity:90});const index=score.tracks[part].notes.length-1;motifs=findMotifs(score,{match});draw();edit(index);};$('#analysisUndo').onclick=()=>{if(!undo.length)return;redo.push(structuredClone(score.tracks[part].notes));score.tracks[part].notes=undo.pop();$('#analysisRedo').disabled=false;changed();$('#analysisUndo').disabled=!undo.length;};
  $('#analysisRedo').onclick=()=>{if(!redo.length)return;undo.push(structuredClone(score.tracks[part].notes));score.tracks[part].notes=redo.pop();changed();$('#analysisRedo').disabled=!redo.length;$('#analysisUndo').disabled=false;};
  function rangeEdit(operation,tidy=false){const from=+$('#analysisStart').value,to=+$('#analysisEnd').value;if(from<0||to<=from||to>score.length)throw Error('Select an A–B range inside the song.');const copy=structuredClone(score);copy.tracks[part].notes=copy.tracks[part].notes.flatMap(n=>n.tick>=from&&n.tick<to?operation({...n}):[n]);if(tidy){const byNote=new Map();for(const n of copy.tracks[part].notes)byNote.set(n.tick+':'+n.key,n);const ns=[...byNote.values()].sort((a,b)=>a.tick-b.tick||a.key-b.key),last=new Map();for(const n of ns){const before=last.get(n.key);if(before&&before.tick+before.duration>n.tick)before.duration=n.tick-before.tick;last.set(n.key,n);}copy.tracks[part].notes=ns;}checkScore(copy,{arranging:true});remember();score.tracks[part].notes=copy.tracks[part].notes;changed();}
  $('#analysisTransposeUp').onclick=safe(()=>rangeEdit(n=>[{...n,key:n.key+1}]));$('#analysisTransposeDown').onclick=safe(()=>rangeEdit(n=>[{...n,key:n.key-1}]));$('#analysisDeleteRange').onclick=safe(()=>rangeEdit(()=>[]));$('#analysisQuantize').onclick=safe(()=>rangeEdit(n=>{const tick=Math.min(score.length-1,Math.round(n.tick/quantum)*quantum);return[{...n,tick,duration:Math.min(score.length-tick,Math.max(quantum,Math.round(n.duration/quantum)*quantum))}];},true));
  $('#analysisMIDI').onclick=safe(()=>api.save(new Blob([writeMIDI(score)],{type:'audio/midi'}),t.name.replace(/[^a-z0-9]+/gi,'_')+'_edited.mid'));$('#analysisGenerate').onclick=safe(()=>generate(t,score,{track:part,start:+$('#analysisStart').value,end:+$('#analysisEnd').value}));draw();
 }
 function generate(t,reference,range){return referenceComposer(api,t,reference,range);}
 function generateFrom(t){if(!t)throw Error('Choose a source song.');const {score}=musicScore(t.asset),track=score.tracks.findIndex(t=>t.notes.length),first=Math.min(...score.tracks[track].notes.map(n=>n.tick));return generate(t,score,{track,start:first,end:Math.min(score.length,first+384)});}

 return{open,generate,generateFrom};
}
